// The vulnerability-intelligence mirror (INTEL-001, CONTEXT_PACK §7, §8.6, §8.9). Reference tables (CVE, KEV, EPSS, OSV,
// CWE, OWASP, sync state) hold global, tenant-less data: the application role may only read them, and writes come from
// the ingestion jobs under their own role (INTEL-002..006). `finding_intel` is the only tenant-scoped table here.
// Migration generated by `pnpm db:generate` from this file, then reviewed: FORCE ROW LEVEL SECURITY, the grants and the
// `updated_at` trigger are appended by hand because Drizzle does not model them.

import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgPolicy,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uuid,
} from 'drizzle-orm/pg-core';

import {
  CPE_MATCHES_MAX_BYTES,
  CVE_DESCRIPTION_MAX_CHARS,
  CVE_ID_PATTERN,
  GHSA_ID_PATTERN,
  INTEL_CWE_IDS_MAX,
  INTEL_JSON_MAX_BYTES,
  INTEL_SOURCES,
  OWASP_SCHEMES,
  SOURCE_SYNC_STATUSES,
  SYNC_ERROR_MAX_CHARS,
} from '@blackwing/contracts';

import { tenantIdColumn, tenantIdIndex } from '../columns.js';
import { TENANT_PREDICATE } from './columns.js';
import { findings } from './findings.js';

const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

/** SQL list of string literals for a CHECK, from a constant the code owns (never user input). */
const sqlList = (values: readonly string[]) => sql.raw(values.map((v) => `'${v}'`).join(', '));

/** Escaped regex literal for a CHECK, from a constant the code owns. */
const sqlRegex = (pattern: RegExp) => sql.raw(`'${pattern.source}'`);

/**
 * CVSS block shape: NULL, or an object with the vector and the base score (the TS schema recomputes the score). COALESCE
 * matters: a missing key gives a NULL type, and a CHECK that evaluates to NULL passes.
 */
const cvssBlockCheck = (column: string) =>
  `${column} IS NULL OR (jsonb_typeof(${column}) = 'object' AND COALESCE(jsonb_typeof(${column}->'vector'), '') = 'string' AND COALESCE(jsonb_typeof(${column}->'baseScore'), '') = 'number')`;

/** One CVE record. Keyed by `cve_id`: a second source for the same CVE upserts, it never duplicates. */
export const cveRecords = pgTable(
  'cve_records',
  {
    cveId: text('cve_id').primaryKey(),
    published: ts('published'),
    lastModified: ts('last_modified'),
    /** `{ vector, baseScore }` or NULL when the source publishes no v3.1 vector. Never a fabricated score. */
    cvssV31: jsonb('cvss_v31'),
    /** `{ vector, baseScore }` or NULL when the source publishes no v4.0 vector. */
    cvssV40: jsonb('cvss_v40'),
    cweIds: text('cwe_ids')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    /** The CPE match configuration as published. Size-capped per record (CHECK below). */
    cpeMatches: jsonb('cpe_matches')
      .notNull()
      .default(sql`'[]'::jsonb`),
    description: text('description'),
    /** The source's own last-modified instant: an upsert only overwrites with a newer or equal value. */
    sourceUpdated: ts('source_updated'),
  },
  (t) => [
    index('cve_records_cpe_matches_gin_idx').using('gin', t.cpeMatches.op('jsonb_path_ops')),
    index('cve_records_cwe_ids_gin_idx').using('gin', t.cweIds),
    check('cve_records_cve_id_check', sql`${t.cveId} ~ ${sqlRegex(CVE_ID_PATTERN)}`),
    check('cve_records_cvss_v31_check', sql.raw(cvssBlockCheck('"cve_records"."cvss_v31"'))),
    check('cve_records_cvss_v40_check', sql.raw(cvssBlockCheck('"cve_records"."cvss_v40"'))),
    check(
      'cve_records_cwe_ids_check',
      sql`cardinality(${t.cweIds}) <= ${sql.raw(String(INTEL_CWE_IDS_MAX))}`,
    ),
    check(
      'cve_records_cpe_matches_check',
      sql`jsonb_typeof(${t.cpeMatches}) = 'array' AND octet_length(${t.cpeMatches}::text) <= ${sql.raw(String(CPE_MATCHES_MAX_BYTES))}`,
    ),
    check(
      'cve_records_description_check',
      sql`${t.description} IS NULL OR length(${t.description}) <= ${sql.raw(String(CVE_DESCRIPTION_MAX_CHARS))}`,
    ),
  ],
);

/** CISA KEV: CVEs with confirmed in-the-wild exploitation. */
export const kevEntries = pgTable(
  'kev_entries',
  {
    cveId: text('cve_id').primaryKey(),
    dateAdded: date('date_added', { mode: 'string' }).notNull(),
    dueDate: date('due_date', { mode: 'string' }),
    knownRansomware: boolean('known_ransomware').notNull().default(false),
    notes: text('notes'),
  },
  (t) => [
    check('kev_entries_cve_id_check', sql`${t.cveId} ~ ${sqlRegex(CVE_ID_PATTERN)}`),
    check(
      'kev_entries_notes_check',
      sql`${t.notes} IS NULL OR length(${t.notes}) <= ${sql.raw(String(SYNC_ERROR_MAX_CHARS))}`,
    ),
  ],
);

/** FIRST EPSS: probability (and percentile) that a CVE is exploited in the next 30 days, per score date. */
export const epssScores = pgTable(
  'epss_scores',
  {
    cveId: text('cve_id').primaryKey(),
    epss: numeric('epss', { mode: 'number' }).notNull(),
    percentile: numeric('percentile', { mode: 'number' }).notNull(),
    scoreDate: date('score_date', { mode: 'string' }).notNull(),
  },
  (t) => [
    index('epss_scores_score_date_idx').on(t.scoreDate),
    check('epss_scores_cve_id_check', sql`${t.cveId} ~ ${sqlRegex(CVE_ID_PATTERN)}`),
    check(
      'epss_scores_range_check',
      sql`${t.epss} BETWEEN 0 AND 1 AND ${t.percentile} BETWEEN 0 AND 1`,
    ),
  ],
);

/** OSV advisories (package ecosystem ranges). `ghsa_id` is set when the advisory is also a GitHub advisory. */
export const osvAdvisories = pgTable(
  'osv_advisories',
  {
    osvId: text('osv_id').primaryKey(),
    aliases: text('aliases')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    ghsaId: text('ghsa_id'),
    ecosystem: text('ecosystem').notNull(),
    package: text('package').notNull(),
    affectedRanges: jsonb('affected_ranges')
      .notNull()
      .default(sql`'[]'::jsonb`),
    severity: jsonb('severity')
      .notNull()
      .default(sql`'[]'::jsonb`),
    modified: ts('modified'),
  },
  (t) => [
    index('osv_advisories_ecosystem_package_idx').on(t.ecosystem, t.package),
    check(
      'osv_advisories_ghsa_id_check',
      sql`${t.ghsaId} IS NULL OR ${t.ghsaId} ~ ${sqlRegex(GHSA_ID_PATTERN)}`,
    ),
    check(
      'osv_advisories_json_check',
      sql`octet_length(${t.affectedRanges}::text) <= ${sql.raw(String(INTEL_JSON_MAX_BYTES))} AND octet_length(${t.severity}::text) <= ${sql.raw(String(INTEL_JSON_MAX_BYTES))}`,
    ),
  ],
);

/** The MITRE CWE catalogue: names, abstraction levels and the relationship graph as published. */
export const cweCatalogue = pgTable(
  'cwe_catalogue',
  {
    cweId: text('cwe_id').primaryKey(),
    name: text('name').notNull(),
    abstraction: text('abstraction').notNull(),
    relationships: jsonb('relationships')
      .notNull()
      .default(sql`'[]'::jsonb`),
  },
  (t) => [
    check('cwe_catalogue_cwe_id_check', sql`${t.cweId} ~ '^CWE-[1-9][0-9]{0,4}$'`),
    check(
      'cwe_catalogue_relationships_check',
      sql`octet_length(${t.relationships}::text) <= ${sql.raw(String(INTEL_JSON_MAX_BYTES))}`,
    ),
  ],
);

/** OWASP category mappings, one row per (standard, code). Standards are fixed by `OWASP_SCHEMES`. */
export const owaspMappings = pgTable(
  'owasp_mappings',
  {
    scheme: text('scheme').notNull(),
    code: text('code').notNull(),
    title: text('title').notNull(),
    cweIds: text('cwe_ids')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
  },
  (t) => [
    primaryKey({ name: 'owasp_mappings_pk', columns: [t.scheme, t.code] }),
    check('owasp_mappings_scheme_check', sql`${t.scheme} IN (${sqlList(OWASP_SCHEMES)})`),
    check('owasp_mappings_code_check', sql`length(${t.code}) BETWEEN 1 AND 16`),
  ],
);

/** Incremental sync state per source (§8.9 pins its snapshot date into run manifests). One row per source. */
export const sourceSyncState = pgTable(
  'source_sync_state',
  {
    source: text('source').primaryKey(),
    lastRun: ts('last_run'),
    lastCursor: text('last_cursor'),
    recordCount: integer('record_count').notNull().default(0),
    status: text('status').notNull().default('idle'),
    lastError: text('last_error'),
  },
  (t) => [
    check('source_sync_state_source_check', sql`${t.source} IN (${sqlList(INTEL_SOURCES)})`),
    check('source_sync_state_status_check', sql`${t.status} IN (${sqlList(SOURCE_SYNC_STATUSES)})`),
    check('source_sync_state_record_count_check', sql`${t.recordCount} >= 0`),
    check(
      'source_sync_state_last_error_check',
      sql`${t.lastError} IS NULL OR length(${t.lastError}) <= ${sql.raw(String(SYNC_ERROR_MAX_CHARS))}`,
    ),
  ],
);

/**
 * The per-tenant join: the mirror's view of a CVE linked to one of the tenant's findings (INTEL-007/009/010 read it).
 * Composite foreign key to `findings(tenant_id, id)`, because a plain foreign key bypasses RLS (§8.6).
 */
export const findingIntel = pgTable(
  'finding_intel',
  {
    tenantId: tenantIdColumn(),
    findingId: uuid('finding_id').notNull(),
    cveId: text('cve_id').notNull(),
    kev: boolean('kev').notNull().default(false),
    epss: numeric('epss', { mode: 'number' }),
    addedAt: ts('added_at').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: 'finding_intel_pk', columns: [t.tenantId, t.findingId, t.cveId] }),
    tenantIdIndex('finding_intel', t.tenantId),
    foreignKey({
      name: 'finding_intel_finding_fk',
      columns: [t.tenantId, t.findingId],
      foreignColumns: [findings.tenantId, findings.id],
    }),
    check('finding_intel_cve_id_check', sql`${t.cveId} ~ ${sqlRegex(CVE_ID_PATTERN)}`),
    check('finding_intel_epss_check', sql`${t.epss} IS NULL OR ${t.epss} BETWEEN 0 AND 1`),
    pgPolicy('finding_intel_tenant_isolation', {
      as: 'permissive',
      for: 'all',
      to: 'public',
      using: TENANT_PREDICATE,
      withCheck: TENANT_PREDICATE,
    }),
  ],
);
